!function(){"use strict";document.addEventListener("DOMContentLoaded",function(){const t=document.getElementById("toggle-theme"),e=document.documentElement;if(t){const n=()=>{const n="light"===e.getAttribute("data-theme");t.setAttribute("aria-label",n?"Switch to dark mode":"Switch to light mode")};t.addEventListener("click",()=>{const t="light"===e.getAttribute("data-theme")?"dark":"light";e.setAttribute("data-theme",t),n()}),n()}const n=document.getElementById("searchInput");document.addEventListener("keydown",t=>{if(!n||"/"!==t.key||t.metaKey||t.ctrlKey||t.altKey)return;const e=document.activeElement?.tagName;"INPUT"===e||"TEXTAREA"===e||document.activeElement?.isContentEditable||(t.preventDefault(),n.focus())}),document.querySelectorAll("[data-copy]").forEach(t=>{t.addEventListener("click",async()=>{const e=t.getAttribute("data-copy")||"";try{await navigator.clipboard.writeText(e),t.setAttribute("data-copied","true"),window.setTimeout(()=>t.removeAttribute("data-copied"),1600)}catch(t){console.error(t)}})})})}();